import React, { useState } from 'react';
import './styles.css';

let nextId = 1;

export default function App() {
  const [name, setName] = useState('');
  const [items, setItems] = useState([]);
  const [hint, setHint] = useState('');
  const [filter, setFilter] = useState('all');

  function handleAdd() {
    const trimmed = name.trim();
    if (trimmed === '') {
      setHint('请输入商品名称');
      return;
    }
    setItems([...items, { id: nextId++, name: trimmed, quantity: 1, purchased: false }]);
    setName('');
    setHint('');
  }

  function handleIncrease(id) {
    setItems(items.map((item) =>
      item.id === id ? { ...item, quantity: item.quantity + 1 } : item
    ));
  }

  function handleDecrease(id) {
    setItems(items.map((item) =>
      item.id === id ? { ...item, quantity: Math.max(1, item.quantity - 1) } : item
    ));
  }

  function handleToggle(id) {
    setItems(items.map((item) =>
      item.id === id ? { ...item, purchased: !item.purchased } : item
    ));
  }

  function handleDelete(id) {
    setItems(items.filter((item) => item.id !== id));
  }

  const visibleItems = items.filter((item) => {
    if (filter === 'pending') return !item.purchased;
    if (filter === 'purchased') return item.purchased;
    return true;
  });

  const kinds = items.length;
  const pendingTotal = items
    .filter((item) => !item.purchased)
    .reduce((sum, item) => sum + item.quantity, 0);

  return (
    <main>
      <h1>购物清单</h1>
      <div className="add-row">
        <input
          data-testid="item-input"
          type="text"
          placeholder="商品名称"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <button type="button" onClick={handleAdd}>添加</button>
      </div>
      <p data-testid="hint" className="hint">{hint}</p>

      <div className="stats">
        <span data-testid="stat-kinds">商品种类：{kinds}</span>
        <span data-testid="stat-pending">待购买件数：{pendingTotal}</span>
      </div>

      <div className="filters">
        <button type="button" className={filter === 'all' ? 'active' : ''} onClick={() => setFilter('all')}>全部</button>
        <button type="button" className={filter === 'pending' ? 'active' : ''} onClick={() => setFilter('pending')}>待购买</button>
        <button type="button" className={filter === 'purchased' ? 'active' : ''} onClick={() => setFilter('purchased')}>已购买</button>
      </div>

      <ul className="item-list">
        {visibleItems.map((item) => (
          <li key={item.id} data-testid="item-row" className="item-row">
            <span className="item-name">{item.name}</span>
            <span data-testid="item-quantity">数量：{item.quantity}</span>
            <span data-testid="item-status" className="item-status">
              {item.purchased ? '已购买' : '待购买'}
            </span>
            <button type="button" onClick={() => handleDecrease(item.id)}>减少</button>
            <button type="button" onClick={() => handleIncrease(item.id)}>增加</button>
            <button type="button" onClick={() => handleToggle(item.id)}>切换状态：{item.name}</button>
            <button type="button" onClick={() => handleDelete(item.id)}>删除</button>
          </li>
        ))}
      </ul>
    </main>
  );
}

